package com.fasterxml.jackson.core.json.async;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.async.ByteArrayFeeder;
import com.fasterxml.jackson.core.async.NonBlockingInputFeeder;
import com.fasterxml.jackson.core.io.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NonBlockingJsonParser.feedInput
 */
public class NonBlockingJsonParser_feedInput_TriageGen1Test {

    private NonBlockingJsonParser parser;
    private IOContext ioContext;
    private ByteQuadsCanonicalizer sym;

    @Before
    public void setUp() {
        ioContext = IOContext.bootstrap();
        sym = ByteQuadsCanonicalizer.newInstance(null);
        parser = new NonBlockingJsonParser(ioContext, 0, sym);
    }

    /**
     * Helper to access private fields via reflection for state verification
     */
    private Object getField(String fieldName) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(parser);
    }

    /**
     * Helper to set private fields via reflection to simulate specific states
     */
    private void setField(String fieldName, Object value) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(parser, value);
    }

    @Test
    public void testFeedInput_Success() throws Exception {
        byte[] buf = "{ \"a\": 1 }".getBytes();
        int start = 0;
        int end = buf.length;

        // Initial state check (assuming defaults)
        // _inputPtr = 0, _inputEnd = 0, _endOfInput = false, _origBufferLen = 0, _currInputProcessed = 0

        parser.feedInput(buf, start, end);

        assertEquals(buf, getField("_inputBuffer"));
        assertEquals(start, getField("_inputPtr"));
        assertEquals(end, getField("_inputEnd"));
        assertEquals(end - start, getField("_origBufferLen"));
        assertEquals(0, getField("_currInputProcessed"));
        // _currInputRowStart = 0 - (0 - 0) = 0
        assertEquals(0, getField("_currInputRowStart"));
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_UndecodedBytesRemaining() throws Exception {
        // Simulate state where _inputPtr < _inputEnd
        setField("_inputPtr", 0);
        setField("_inputEnd", 5);

        byte[] buf = new byte[10];
        parser.feedInput(buf, 0, 10);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_EndBeforeStart() throws Exception {
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);

        byte[] buf = new byte[10];
        parser.feedInput(buf, 5, 2);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_AlreadyClosed() throws Exception {
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", true);

        byte[] buf = new byte[10];
        parser.feedInput(buf, 0, 10);
    }

    @Test
    public void testFeedInput_ConsecutiveCalls_UpdatesPointersCorrectly() throws Exception {
        // First call
        byte[] buf1 = "{\"a\"".getBytes();
        parser.feedInput(buf1, 0, buf1.length);

        long firstProcessed = (long) getField("_currInputProcessed");
        int firstOrigLen = (int) getField("_origBufferLen");
        int firstRowStart = (int) getField("_currInputRowStart");

        // Second call
        byte[] buf2 = ": 1}".getBytes();
        // To simulate successful second call, we must ensure _inputPtr == _inputEnd from first call
        // In actual parser logic, the consumer calls nextToken, which advances _inputPtr.
        // We simulate that the consumer processed buf1 completely.
        setField("_inputPtr", buf1.length); 

        parser.feedInput(buf2, 0, buf2.length);

        assertEquals(firstProcessed + firstOrigLen, getField("_currInputProcessed"));
        assertEquals(buf2, getField("_inputBuffer"));
        assertEquals(0, getField("_inputPtr"));
        assertEquals(buf2.length, getField("_inputEnd"));

        // Verify row start adjustment: 
        // _currInputRowStart = start - (_inputEnd - _currInputRowStart)
        // Using the values from the first call to simulate a continuous stream
        // If first call had start=0, end=7, rowStart=0. 
        // Second call: start=0, _inputEnd=7, _currInputRowStart=0 -> 0 - (7 - 0) = -7
        // This logic in the source code is used to maintain relative positioning.
    }

    @Test
    public void testFeedInput_RowStartAdjustment() throws Exception {
        // Setup state: _inputPtr = 10, _inputEnd = 10, _currInputRowStart = 5
        setField("_inputPtr", 10);
        setField("_inputEnd", 10);
        setField("_currInputRowStart", 5);
        setField("_origBufferLen", 0);
        setField("_currInputProcessed", 100);

        byte[] buf = new byte[20];
        int start = 5;
        int end = 15;

        parser.feedInput(buf, start, end);

        // Calculation: _currInputRowStart = start - (_inputEnd - _currInputRowStart)
        // _currInputRowStart = 5 - (10 - 5) = 0
        assertEquals(0, getField("_currInputRowStart"));
        assertEquals(100, getField("_currInputProcessed"));
    }
}
